-- Generated by `prisma migrate diff`, then hand-edited (D31).
-- Prisma's version added both columns as NOT NULL with no default, which fails on a table
-- that already has rows: ERROR: column "fullName" of relation "User" contains null values.
-- Fix: add with DEFAULT '' so existing rows get a value, then drop the default so new
-- inserts must supply one. The old "name" values are lost: a rename is DROP + ADD here.

-- AlterTable
ALTER TABLE "User" DROP COLUMN "name",
ADD COLUMN     "fullName" TEXT NOT NULL DEFAULT '',
ADD COLUMN     "phone" TEXT NOT NULL DEFAULT '';

ALTER TABLE "User" ALTER COLUMN "fullName" DROP DEFAULT,
ALTER COLUMN "phone" DROP DEFAULT;
